      function getCountryFormats(country) {
        return country ? formats[country.toUpperCase()] : null;
      }

      function getFormattedPhone(country, phone) {
        var countryFormats = getCountryFormats(country),
          input;

        if (!countryFormats) {
          return phone;
        }

        var result = '',
          prefix = countryFormats.prefix,
          format = countryFormats.format,
          mask,
          length;

        if (!phone || phone.substring(0, prefix.length) !== prefix) {
          input = phone.replace(/[\(\)\-]/g, '');


          if (input[0] === '+' && input.indexOf(' ') > -1) {
            input = input.slice(phone.indexOf(' '));
          } else {
            input = phone.replace(/[\+\s]+/g, '');
          }

            return getFormattedPhone(country, prefix + input);
        }

        if (!format) {
          return phone;
        } else {
          input = phone.replace(/[\+\(\)\-\s]/g, '');
          for (var index = 0, formatIndex = 0; formatIndex < format.length; formatIndex++) {
            var num = input[index];
            mask = format[formatIndex];

            if (!num) {
              break;
            }

            if (mask !== '.') {
              result += mask;
            } else {
              result += num;
              index++;
            }
          }

          length = formatIndex - 1;
          if (phone.length < format.length) {
            for (mask = format[length]; mask !== '.'; mask = format[++length]) {
              result += mask;
            }
          } else if (phone.length > format.length) {
            result += phone.slice(format.length).replace(/[\+\(\)\-\s]/g, '');
          }
        }

        return result;
      }

      function isPrefixValid(phone) {
        if (!phone || phone[0] !== '+') {
          return false;
        } else {
          var prefix = phone.split(' ')[0];

          for(var code in formats) {
            var formatPrefix = formats[code].prefix;

            if (formatPrefix === prefix) {
              return true;
            }
          }

          return false;
        }
      }

